ï»¿use coaptic::{Endpoint,storage::{AsyncDatagramIo,DatagramTransport}};
use std::{cell::RefCell,io,io::Write, future::{Future,poll_fn},pin::pin,time::Instant};
#[link(name="kernel32")]
unsafe extern "system" {
 fn GetCurrentThread()->*mut std::ffi::c_void;
 fn QueryThreadCycleTime(thread:*mut std::ffi::c_void,out:*mut u64)->i32;
}
fn stamp()->(u64,Instant) {
 let mut value=0;
 // The pseudo-handle identifies this thread, and the output remains live during the call.
 assert_ne!(unsafe{QueryThreadCycleTime(GetCurrentThread(), &mut value)},0);
 (value,Instant::now())
}
thread_local!{static ROWS: RefCell<[[u64;6];3]> = const{RefCell::new([[0;6];3])};}
pub fn enabled()->bool{std::env::var_os("COAPTIC_SEND_TRACE").is_some()}
pub struct Trace<T>(pub T);
async fn trace<F:Future>(idx:usize,f:F)->F::Output{
 let mut f=pin!(f);
 let mut pending:Option<Instant>=None;
 poll_fn(|cx|{
    let (c,start)=stamp();
    let polled=f.as_mut().poll(cx);
    let (end,wall)=stamp();
    let off=pending.take().map_or(0,|p|(start-p).as_nanos() as u64);
    ROWS.with_borrow_mut(|rows|{
       let r=&mut rows[idx];r[0]+=1;r[1]+=u64::from(polled.is_pending());r[2]+=end-c;
       r[3]+=(wall-start).as_nanos() as u64;r[4]+=off;r[5]+=u64::from(off>0);
    });
    if polled.is_pending(){pending=Some(wall)}
    polled
 }).await
}
impl<T:DatagramTransport> DatagramTransport for Trace<T>{type Error=T::Error;}
impl<T:AsyncDatagramIo> AsyncDatagramIo for Trace<T>{
 async fn recv(&mut self,b:&mut[u8])->Result<(usize,Endpoint),T::Error>{trace(0,self.0.recv(b)).await}
 async fn send(&mut self,d:Endpoint,b:&[u8])->Result<usize,T::Error>{
   let res=trace(1,self.0.send(d,b)).await;
   let (c,start)=stamp();let (end,wall)=stamp();
   ROWS.with_borrow_mut(|rows|{let cal=&mut rows[2];cal[0]+=1;cal[2]+=end-c;cal[3]+=(wall-start).as_nanos() as u64;
     if matches!(cal[0],128|2176){let p=std::env::var_os("COAPTIC_SEND_TRACE").unwrap();
      writeln!(std::fs::OpenOptions::new().append(true).create(true).open(p).unwrap(),"{:?}",rows).unwrap();}
   });res
 }
}
